begin;
create table public.rental_collection_preferences(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),tenancy_id uuid not null unique references public.rental_tenancies(id),channel text not null default 'email' check(channel in('email','sms','whatsapp','none')),timezone text not null default 'Africa/Johannesburg',suppressed_until timestamptz,suppression_reason text,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.rental_collection_reminders(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),tenancy_id uuid not null references public.rental_tenancies(id),reminder_stage text not null check(reminder_stage in('current','overdue_7','overdue_30','overdue_60','overdue_90')),channel text not null check(channel in('email','sms','whatsapp')),status text not null default 'queued' check(status in('queued','sent','suppressed','cancelled')),balance_snapshot numeric(14,2) not null,scheduled_for timestamptz not null default now(),dedupe_date date not null default((now() at time zone 'UTC')::date),sent_at timestamptz,suppressed_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(tenancy_id,reminder_stage,dedupe_date));
create index rental_collection_reminders_queue_idx on public.rental_collection_reminders(organisation_id,status,scheduled_for);alter table public.rental_collection_preferences enable row level security;alter table public.rental_collection_reminders enable row level security;revoke all on public.rental_collection_preferences,public.rental_collection_reminders from anon,authenticated;grant select on public.rental_collection_preferences,public.rental_collection_reminders to authenticated;
create policy rental_collection_preferences_read on public.rental_collection_preferences for select to authenticated using(exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)));create policy rental_collection_reminders_read on public.rental_collection_reminders for select to authenticated using(exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_tenancy_live_outstanding(x uuid) returns numeric language sql stable security definer set search_path='' as $$select coalesce((select sum(amount) from public.rental_financial_charges where tenancy_id=x),0)-coalesce((select sum(amount) from public.rental_financial_allocations where tenancy_id=x),0)+coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=x and adjustment_type='debit'),0)-coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=x and adjustment_type='credit'),0)$$;
create or replace function public.rental_queue_collection_reminder(x uuid,s text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype;p public.rental_collection_preferences%rowtype;b numeric;rid uuid;st text:='queued';ch text:='email';rs text;begin if auth.uid() is null or s not in('current','overdue_7','overdue_30','overdue_60','overdue_90') then raise exception 'A valid reminder stage is required';end if;select * into t from public.rental_tenancies where id=x for update;if not found or not exists(select 1 from public.rental_properties z where z.id=t.property_id and public.rental_branch_access(z.organisation_id,z.branch_id)) then raise exception 'Not authorized';end if;b:=public.rental_tenancy_live_outstanding(t.id);if b<=0 then raise exception 'No reminder: tenancy has no live outstanding balance';end if;select * into p from public.rental_collection_preferences where tenancy_id=t.id;if found then ch:=p.channel;end if;if ch='none' or(p.suppressed_until is not null and p.suppressed_until>now())then st:='suppressed';rs:=coalesce(p.suppression_reason,'Reminder suppressed by preference');ch:='email';end if;insert into public.rental_collection_reminders(organisation_id,tenancy_id,reminder_stage,channel,status,balance_snapshot,suppressed_reason,created_by)values(t.organisation_id,t.id,s,ch,st,b,rs,auth.uid())on conflict(tenancy_id,reminder_stage,dedupe_date)do nothing returning id into rid;return jsonb_build_object('reminder_id',rid,'status',st,'live_balance',b,'deduplicated',rid is null);end$$;
create or replace function public.rental_send_collection_reminder(x uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_collection_reminders%rowtype;b numeric;begin select * into r from public.rental_collection_reminders where id=x for update;if not found then raise exception 'Reminder not found';end if;b:=public.rental_tenancy_live_outstanding(r.tenancy_id);if r.status<>'queued' then return jsonb_build_object('reminder_id',r.id,'status',r.status,'idempotent',true);end if;if b<=0 then update public.rental_collection_reminders set status='cancelled',suppressed_reason='Balance cleared before send' where id=r.id;return jsonb_build_object('reminder_id',r.id,'status','cancelled');end if;update public.rental_collection_reminders set status='sent',sent_at=now(),balance_snapshot=b where id=r.id;return jsonb_build_object('reminder_id',r.id,'status','sent','live_balance',b);end$$;
create or replace function public.rental_suppress_collection_reminders(x uuid,u timestamptz,rs text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype;begin if auth.uid() is null or u is null or u<=now() or length(btrim(coalesce(rs,'')))=0 then raise exception 'Future suppression end and reason are required';end if;select * into t from public.rental_tenancies where id=x for update;if not found or not exists(select 1 from public.rental_properties z where z.id=t.property_id and public.rental_branch_access(z.organisation_id,z.branch_id)) then raise exception 'Not authorized';end if;insert into public.rental_collection_preferences(organisation_id,tenancy_id,suppressed_until,suppression_reason,updated_by)values(t.organisation_id,t.id,u,btrim(rs),auth.uid())on conflict(tenancy_id)do update set suppressed_until=excluded.suppressed_until,suppression_reason=excluded.suppression_reason,updated_by=excluded.updated_by,updated_at=now();return jsonb_build_object('tenancy_id',t.id,'suppressed_until',u);end$$;
revoke execute on function public.rental_tenancy_live_outstanding(uuid),public.rental_queue_collection_reminder(uuid,text),public.rental_send_collection_reminder(uuid),public.rental_suppress_collection_reminders(uuid,timestamptz,text) from public,anon;grant execute on function public.rental_queue_collection_reminder(uuid,text),public.rental_send_collection_reminder(uuid),public.rental_suppress_collection_reminders(uuid,timestamptz,text) to authenticated;commit;;
